class SettingsEntry:
    """
        Defines all the parameters for a single settings entry.

        * category: Mostly for organizational purposes when displaying options in the
            SettingsQR UI. Potentially an additional sub-level breakout in the menus
            on the device itself, too.

        * selection_options: May be specified as a List(Any) or List(tuple(Any, str)).
          The tuple form is to provide a human-readable display_name. Probably all
          entries should shift to using the tuple form.

        * min_value / max_value: Inclusive bounds enforced by
          `Settings.set_value()` for numeric (free-entry) settings. Values coming
          from untrusted inputs (SettingsQR, settings.json on an SD card) that
          fall outside the range -- or are not integers at all -- are rejected so
          they cannot silently weaken or break dependent crypto operations.
    """

    def __init__(self, category, attr_name, display_name, abbreviated_name=None, visibility=SettingsConstants.VISIBILITY__GENERAL, type=SettingsConstants.TYPE__ENABLED_DISABLED, help_text=None, selection_options=None, default_value=None, min_value=None, max_value=None):
        self.category = category
        self.attr_name = attr_name
        self.display_name = display_name
        self.abbreviated_name = abbreviated_name
        self.visibility = visibility
        self.type = type
        self.help_text = help_text
        self.selection_options = selection_options
        self.default_value = default_value
        self.min_value = min_value
        self.max_value = max_value
        self.__post_init__()

    def __eq__(self, other):
        if type(self) is not type(other):
            return NotImplemented
        return self.category == other.category and self.attr_name == other.attr_name and (self.display_name == other.display_name) and (self.abbreviated_name == other.abbreviated_name) and (self.visibility == other.visibility) and (self.type == other.type) and (self.help_text == other.help_text) and (self.selection_options == other.selection_options) and (self.default_value == other.default_value) and (self.min_value == other.min_value) and (self.max_value == other.max_value)

    def __repr__(self):
        return 'SettingsEntry(' + 'category=' + repr(self.category) + ', ' + 'attr_name=' + repr(self.attr_name) + ', ' + 'display_name=' + repr(self.display_name) + ', ' + 'abbreviated_name=' + repr(self.abbreviated_name) + ', ' + 'visibility=' + repr(self.visibility) + ', ' + 'type=' + repr(self.type) + ', ' + 'help_text=' + repr(self.help_text) + ', ' + 'selection_options=' + repr(self.selection_options) + ', ' + 'default_value=' + repr(self.default_value) + ', ' + 'min_value=' + repr(self.min_value) + ', ' + 'max_value=' + repr(self.max_value) + ')'

    def __post_init__(self):
        if self.type == SettingsConstants.TYPE__ENABLED_DISABLED:
            self.selection_options = SettingsConstants.OPTIONS__ENABLED_DISABLED
        elif self.type == SettingsConstants.TYPE__ENABLED_DISABLED_PROMPT:
            self.selection_options = SettingsConstants.OPTIONS__ENABLED_DISABLED_PROMPT
        elif self.type == SettingsConstants.TYPE__ENABLED_DISABLED_PROMPT_REQUIRED:
            self.selection_options = SettingsConstants.ALL_OPTIONS
        if type(self.default_value) == list and type(self.default_value[0]) == tuple:
            self.default_value = [v[0] for v in self.default_value]
        elif type(self.default_value) == tuple:
            self.default_value = self.default_value[0]
        if not self.abbreviated_name:
            self.abbreviated_name = self.attr_name

    @property
    def selection_options_display_names(self):
        if type(self.selection_options[0]) == tuple:
            return [v[1] for v in self.selection_options]
        else:
            return list(self.selection_options)

    def get_selection_option_value(self, i):
        """ Returns the value of the selection option at index `i` """
        value = self.selection_options[i]
        if type(value) == tuple:
            value = value[0]
        return value

    def get_selection_option_display_name_by_value(self, value):
        for option in self.selection_options:
            if type(option) == tuple:
                option_value = option[0]
                display_name = option[1]
            else:
                option_value = option
                display_name = option
            if option_value == value:
                return _mft(display_name)

    def get_selection_option_value_by_display_name(self, display_name):
        for option in self.selection_options:
            if type(option) == tuple:
                option_value = option[0]
                option_display_name = option[1]
            else:
                option_value = option
                option_display_name = option
            if option_display_name == display_name:
                return option_value

    def to_dict(self):
        if self.selection_options:
            selection_options = []
            for option in self.selection_options:
                if type(option) == tuple:
                    value = option[0]
                    display_name = option[1]
                else:
                    display_name = option
                    value = option
                selection_options.append({'display_name': display_name, 'value': value})
        else:
            selection_options = None
        return {'category': self.category, 'attr_name': self.attr_name, 'abbreviated_name': self.abbreviated_name, 'display_name': self.display_name, 'visibility': self.visibility, 'type': self.type, 'help_text': self.help_text, 'selection_options': selection_options, 'default_value': self.default_value}

